        // Verify initial state
        assertEq(multiplicator.getContractBalance(), INITIAL_BALANCE, "Initial balance mismatch");
        assertEq(multiplicator.totalMultiplications(), 0, "Initial multiplication count should be 0");

        // Execute attack
        attacker.attack{value: ATTACK_VALUE}();

